function fatorial(n) {
  if (n < 0) {
    throw new RangeError("fatorial não definido para negativos");
  }
  if (n === 0 || n === 1) {
    return 1; // caso base
  }
  return n * fatorial(n - 1); // caso recursivo
}

console.log(fatorial(5)); // 120
console.log(fatorial(0)); // 1

function contarProfundidade(n) {
  return contarProfundidade(n + 1);
}

try {
  contarProfundidade(0);
} catch (erro) {
  console.error(erro instanceof RangeError); // true
  console.error(erro.message); // "Maximum call stack size exceeded"
}

function fatorialRecursivo(n) {
  if (n <= 1) return 1;
  return n * fatorialRecursivo(n - 1);
}

function fatorialIterativo(n) {
  let resultado = 1;
  for (let i = 2; i <= n; i++) {
    resultado *= i;
  }
  return resultado;
}

console.log(fatorialRecursivo(6), fatorialIterativo(6)); // 720 720

