const contador = (function () {
  let valor = 0; // estado privado, inacessível de fora

  function incrementar() {
    valor += 1;
    return valor;
  }

  function decrementar() {
    valor -= 1;
    return valor;
  }

  function obterValor() {
    return valor;
  }

  return { incrementar, decrementar, obterValor }; // revealing module pattern
})();

contador.incrementar();
contador.incrementar();
console.log(contador.obterValor()); // 2
console.log(contador.valor); // undefined

