function somaAte(n) {
  if (n <= 0) {
    return 0; // caso base: já não há nada para somar
  }
  return n + somaAte(n - 1); // caso recursivo: n mais a soma até n - 1
}

console.log(somaAte(4)); // 10
console.log(somaAte(1)); // 1
console.log(somaAte(0)); // 0

function potencia(base, expoente) {
  if (expoente === 0) {
    return 1; // caso base
  }
  return base * potencia(base, expoente - 1); // caso recursivo
}

console.log(potencia(2, 10)); // 1024

// potencia(2, 100000) provoca:
// RangeError: Maximum call stack size exceeded
// porque cada chamada recursiva acrescenta uma frame à pilha de chamadas
// e o motor de JavaScript tem um limite de profundidade da pilha.

function potenciaIterativa(base, expoente) {
  let resultado = 1;
  for (let i = 0; i < expoente; i++) {
    resultado *= base;
  }
  return resultado;
}

console.log(potenciaIterativa(2, 100000)); // Infinity - o valor ultrapassa o máximo representável em number, mas não há RangeError nem crescimento da pilha

const carteira = (function () {
  let saldo = 0; // estado privado, só acessível através dos métodos abaixo

  function depositar(valor) {
    if (valor <= 0) {
      throw new Error("O valor a depositar tem de ser positivo");
    }
    saldo += valor;
    return saldo;
  }

  function levantar(valor) {
    if (valor <= 0) {
      throw new Error("O valor a levantar tem de ser positivo");
    }
    if (valor > saldo) {
      throw new Error("Saldo insuficiente");
    }
    saldo -= valor;
    return saldo;
  }

  function obterSaldo() {
    return saldo;
  }

  return { depositar, levantar, obterSaldo };
})();

carteira.depositar(100);
carteira.levantar(30);
console.log(carteira.obterSaldo()); // 70
console.log(carteira.saldo); // undefined - estado encapsulado

const fibonacci = (function () {
  const cache = {}; // estado privado: guarda resultados já calculados

  function calcularRecursivo(n) {
    if (n === 0 || n === 1) {
      return n; // caso base
    }
    if (cache[n] !== undefined) {
      return cache[n]; // já calculado antes, evita recursão repetida
    }
    const resultado = calcularRecursivo(n - 1) + calcularRecursivo(n - 2); // caso recursivo
    cache[n] = resultado; // guarda para reutilizar
    return resultado;
  }

  return { calcular: calcularRecursivo };
})();

console.log(fibonacci.calcular(30)); // 832040, praticamente instantâneo
